"use client";
import { useEffect, useState } from "react";

const URL = 'https://www.themealdb.com/api/json/v1/1/search.php?s='

export default function Home() {

  const [fetchedData, setfetchedData] = useState<any>([])

  const getData = async () => {
    try {
      fetch(URL)
        .then((res) => res.json())
        .then((data) => {
          console.log(data)
          setfetchedData(data.meals)
        })
    } catch (e) {
      console.log(e);
    }
  };

  useEffect(() => {
    getData();
  }, [])


  return (
    <div className="">
      <div className="flex flex-wrap gap-6">
        {fetchedData.map((meal: any) => (
          <div key={meal.idMeal} className="w-full sm:w-[45%] md:w-[30%] max-w-xs shadow-lg overflow-hidden transform transition hover:scale-105 duration-300 flex gap-2">
            <div className="w-full aspect-[4/3] max-w-48">
              <img
                src={meal.strMealThumb}
                alt={meal.strMeal}
                className="w-full h-full object-cover"
              />
            </div>
            <div>
              <h2 key={meal.idMeal} className="font-bold">{meal.strMeal}</h2>
              <p>{meal.strArea}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
